sys_script.script:
(function executeRule(current, previous) {

    gs.info('========== BR1 INSERT START ==========');

    var skillIds = current.skills.toString().split(',');

    gs.info('Total skills found: ' + skillIds.length);

    for (var i = 0; i < skillIds.length; i++) {

        var skillId = skillIds[i].trim();

        if (!skillId) {
            continue;
        }

        gs.info('Creating Staff Skill for skill: ' + skillId);

        var skill = new GlideRecord('x_snc_flowops_staff_skill');

        if (!skill.isValid()) {
            gs.error('ERROR: Staff Skill table is invalid');
            return;
        }

        skill.initialize();

        skill.setValue('staff', current.getValue('staff'));
        skill.setValue('staff_shift', current.getUniqueValue());
        skill.setValue('property', current.getValue('property'));
        skill.setValue('skill_category', skillId);
        skill.setValue('proficiency_level', current.getValue('proficiency_level'));
        skill.setValue('availability_status', 'available');

        var newId = skill.insert();

        if (newId) {
            gs.info('SUCCESS: Staff Skill created = ' + newId);
        } else {
            gs.error(
                'FAILED: Staff Skill not created for skill ' +
                skillId +
                ' | Error = ' +
                skill.getLastErrorMessage()
            );
        }
    }

    gs.info('========== BR1 INSERT END ==========');

})(current, previous);
